; ------------------------------------------------------------------------
; music_songs.s -- the central music bank (generated by tools/gen_music_songs.py)
;
; All songs live here as fixed-stride 578-byte blocks. The fixed engine's
; music_select_song maps this bank, copies the chosen song's block into a
; fixed-RAM cache, and restores the scene bank. Entry 0 is the avenue theme;
; entry 1 is the bar interior (from music/bar_interior.txt). Every song
; reserves 96 step slots; scenes and the title use fewer and pad the rest.
; ------------------------------------------------------------------------

.export music_song_ptrs

.segment "CODE"
; Song pointer table at $8000 so the fixed engine can find song N by index.
music_song_ptrs:
        .word song_avenue
        .word song_bar
        .word song_mart
        .word song_sewer
        .word song_park
        .word song_casino
        .word song_zoo
        .word song_title

